@import "tailwindcss";

@theme {
  --color-navy-950: #0a1628;
  --color-navy-900: #0D1B2A;
  --color-navy-800: #152238;
  --color-navy-700: #1B2838;
  --color-navy-600: #1e3a5f;
  --color-navy-500: #2a4a7f;
  --color-accent-400: #00B4D8;
  --color-accent-500: #0096c7;
  --color-accent-600: #0077B6;
  --color-accent-700: #023e8a;
  --color-teal-400: #48cae4;
  --color-teal-500: #00b4d8;
  --color-brand-green: #6CC24A;
  --font-display: 'Sora', sans-serif;
  --font-body: 'Space Grotesk', sans-serif;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  background-color: #0a1628;
  color: #e0e6f0;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-display);
}

/* Gradient mesh background */
.bg-mesh {
  background:
    radial-gradient(ellipse 80% 60% at 20% 0%, rgba(0, 180, 216, 0.08) 0%, transparent 50%),
    radial-gradient(ellipse 60% 80% at 80% 40%, rgba(0, 119, 182, 0.06) 0%, transparent 50%),
    radial-gradient(ellipse 50% 50% at 50% 100%, rgba(108, 194, 74, 0.04) 0%, transparent 50%),
    #0a1628;
}

/* Grid pattern overlay */
.bg-grid {
  background-image:
    linear-gradient(rgba(0, 180, 216, 0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 180, 216, 0.03) 1px, transparent 1px);
  background-size: 60px 60px;
}

/* Glow effects */
.glow-accent {
  box-shadow: 0 0 40px rgba(0, 180, 216, 0.15), 0 0 80px rgba(0, 180, 216, 0.05);
}

.glow-green {
  box-shadow: 0 0 30px rgba(108, 194, 74, 0.15);
}

/* Glass card */
.glass {
  background: rgba(21, 34, 56, 0.7);
  backdrop-filter: blur(12px);
  border: 1px solid rgba(0, 180, 216, 0.1);
}

/* Animated border */
.animated-border {
  position: relative;
  overflow: hidden;
}
.animated-border::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 2px;
  background: linear-gradient(90deg, transparent, #00B4D8, transparent);
  animation: borderSlide 3s ease-in-out infinite;
}

@keyframes borderSlide {
  0%, 100% { transform: translateX(-100%); }
  50% { transform: translateX(100%); }
}

/* Pulse ring */
.pulse-ring {
  animation: pulseRing 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}
@keyframes pulseRing {
  0% { box-shadow: 0 0 0 0 rgba(0, 180, 216, 0.4); }
  70% { box-shadow: 0 0 0 15px rgba(0, 180, 216, 0); }
  100% { box-shadow: 0 0 0 0 rgba(0, 180, 216, 0); }
}

/* Fade in up animation */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(30px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.animate-fade-in-up {
  animation: fadeInUp 0.6s ease-out forwards;
}

/* Stagger delays */
.delay-100 { animation-delay: 0.1s; }
.delay-200 { animation-delay: 0.2s; }
.delay-300 { animation-delay: 0.3s; }
.delay-400 { animation-delay: 0.4s; }
.delay-500 { animation-delay: 0.5s; }

/* Scrollbar */
::-webkit-scrollbar {
  width: 6px;
}
::-webkit-scrollbar-track {
  background: #0a1628;
}
::-webkit-scrollbar-thumb {
  background: rgba(0, 180, 216, 0.3);
  border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
  background: rgba(0, 180, 216, 0.5);
}

/* Form styles */
input:focus, select:focus, textarea:focus {
  outline: none;
  border-color: #00B4D8 !important;
  box-shadow: 0 0 0 3px rgba(0, 180, 216, 0.15);
}

/* Accordion animation */
.accordion-content {
  overflow: hidden;
  transition: max-height 0.35s ease, opacity 0.35s ease;
}
.accordion-content.closed {
  max-height: 0;
  opacity: 0;
}
.accordion-content.open {
  max-height: 500px;
  opacity: 1;
}

/* Tab underline animation */
.tab-underline {
  position: relative;
}
.tab-underline::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 2px;
  background: #00B4D8;
  transition: width 0.3s ease;
}
.tab-underline.active::after {
  width: 100%;
}

/* Progress bar animation */
.progress-fill {
  transition: width 1.5s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Circular stat */
.circular-stat circle {
  transition: stroke-dashoffset 2s ease;
}

/* Cookie banner slide */
.cookie-banner {
  transition: transform 0.4s ease, opacity 0.4s ease;
}
.cookie-banner.hidden {
  transform: translateY(100%);
  opacity: 0;
  pointer-events: none;
}

