import React, { useState, useEffect } from 'react';
import { Menu, X, ChevronDown } from 'lucide-react';

const navLinks = [
  {
    label: 'Platform',
    children: [
      { label: 'Platform Overview', href: 'platform-overview.html' },
      { label: 'Security', href: 'security.html' },
      { label: 'Integration', href: 'integration.html' },
    ],
  },
  { label: 'Solutions', href: '#solutions' },
  { label: 'Company', href: '#company' },
];

export default function Nav() {
  const [mobileOpen, setMobileOpen] = useState(false);
  const [platformOpen, setPlatformOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  const isHome = window.location.pathname.endsWith('index.html') || window.location.pathname === '/' || window.location.pathname.endsWith('/output/');

  return (
    <nav className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${scrolled ? 'bg-navy-950/95 backdrop-blur-md border-b border-white/5 shadow-lg' : 'bg-transparent'}`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16 lg:h-20">
          <a href="index.html" className="flex items-center gap-2 flex-shrink-0">
            <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-accent-400 to-accent-600 flex items-center justify-center">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2.5" strokeLinecap="round">
                <path d="M12 2L2 7l10 5 10-5-10-5z"/>
                <path d="M2 17l10 5 10-5"/>
                <path d="M2 12l10 5 10-5"/>
              </svg>
            </div>
            <span className="text-lg font-bold text-white font-display tracking-tight">WellStream</span>
          </a>

          {/* Desktop nav */}
          <div className="hidden lg:flex items-center gap-8">
            {navLinks.map((link) =>
              link.children ? (
                <div key={link.label} className="relative" onMouseEnter={() => setPlatformOpen(true)} onMouseLeave={() => setPlatformOpen(false)}>
                  <button className="flex items-center gap-1 text-sm text-gray-300 hover:text-white transition-colors py-2 font-medium">
                    {link.label}
                    <ChevronDown size={14} className={`transition-transform duration-200 ${platformOpen ? 'rotate-180' : ''}`} />
                  </button>
                  {platformOpen && (
                    <div className="absolute top-full left-0 mt-1 py-2 w-56 glass rounded-xl border border-white/10 shadow-2xl">
                      {link.children.map((child) => (
                        <a key={child.label} href={child.href} className="block px-4 py-2.5 text-sm text-gray-300 hover:text-white hover:bg-white/5 transition-colors">
                          {child.label}
                        </a>
                      ))}
                    </div>
                  )}
                </div>
              ) : (
                <a key={link.label} href={isHome ? link.href : `index.html${link.href}`} className="text-sm text-gray-300 hover:text-white transition-colors font-medium">
                  {link.label}
                </a>
              )
            )}
          </div>

          <div className="hidden lg:flex items-center gap-4">
            <a href="request-demo.html" className="inline-flex items-center gap-2 bg-accent-500 hover:bg-accent-400 text-white text-sm font-semibold px-5 py-2.5 rounded-lg transition-all duration-200 shadow-lg shadow-accent-500/20 hover:shadow-accent-400/30">
              Request A Demo
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M5 12h14M12 5l7 7-7 7"/></svg>
            </a>
          </div>

          {/* Mobile toggle */}
          <button onClick={() => setMobileOpen(!mobileOpen)} className="lg:hidden text-white p-2">
            {mobileOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>
      </div>

      {/* Mobile menu */}
      {mobileOpen && (
        <div className="lg:hidden bg-navy-900/98 backdrop-blur-md border-t border-white/5">
          <div className="px-4 py-4 space-y-3">
            <div className="pb-2 border-b border-white/5">
              <p className="text-xs font-semibold text-accent-400 uppercase tracking-wider mb-2">Platform</p>
              <a href="platform-overview.html" className="block py-2 text-gray-300 hover:text-white">Platform Overview</a>
              <a href="security.html" className="block py-2 text-gray-300 hover:text-white">Security</a>
              <a href="integration.html" className="block py-2 text-gray-300 hover:text-white">Integration</a>
            </div>
            <a href="#solutions" className="block py-2 text-gray-300 hover:text-white">Solutions</a>
            <a href="#company" className="block py-2 text-gray-300 hover:text-white">Company</a>
            <a href="request-demo.html" className="block w-full text-center bg-accent-500 hover:bg-accent-400 text-white font-semibold py-3 rounded-lg mt-4 transition-colors">
              Request A Demo
            </a>
          </div>
        </div>
      )}
    </nav>
  );
}

