import React, { useState, useEffect } from 'react';
import { Menu, X, ChevronDown } from 'lucide-react';

const navLinks = [
  {
    label: 'Platform',
    children: [
      { label: 'Platform Overview', href: 'platform-overview.html' },
      { label: 'Security', href: 'security.html' },
      { label: 'Integration', href: 'integration.html' },
    ],
  },
  { label: 'Solutions', href: '#solutions' },
  { label: 'Company', href: '#company' },
];

export default function Nav() {
  const [mobileOpen, setMobileOpen] = useState(false);
  const [platformOpen, setPlatformOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  const isHome = window.location.pathname.endsWith('index.html') || window.location.pathname === '/' || window.location.pathname.endsWith('/output/');

  return (
    <nav className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${scrolled ? 'bg-navy-950/95 backdrop-blur-md border-b border-white/5 shadow-lg' : 'bg-transparent'}`}>
