                  <button className="flex items-center gap-1 text-sm text-gray-300 hover:text-white transition-colors py-2 font-medium">
                    {link.label}
                    <ChevronDown size={14} className={`transition-transform duration-200 ${platformOpen ? 'rotate-180' : ''}`} />
                  </button>
                  {platformOpen && (
                    <div className="absolute top-full left-0 mt-1 py-2 w-56 glass rounded-xl border border-white/10 shadow-2xl">
                      {link.children.map((child) => (
                        <a key={child.label} href={child.href} className="block px-4 py-2.5 text-sm text-gray-300 hover:text-white hover:bg-white/5 transition-colors">
                          {child.label}
