              <a href="integration.html" className="block py-2 text-gray-300 hover:text-white">Integration</a>
            </div>
            <a href="#solutions" className="block py-2 text-gray-300 hover:text-white">Solutions</a>
            <a href="#company" className="block py-2 text-gray-300 hover:text-white">Company</a>
            <a href="request-demo.html" className="block w-full text-center bg-accent-500 hover:bg-accent-400 text-white font-semibold py-3 rounded-lg mt-4 transition-colors">
