import React, { useState, useEffect } from 'react';
import { X } from 'lucide-react';

export default function CookieBanner() {
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const stored = localStorage.getItem('wellstream-cookies');
    if (!stored) {
      setTimeout(() => setVisible(true), 800);
    }
  }, []);

  const handleAction = (accepted: boolean) => {
    localStorage.setItem('wellstream-cookies', JSON.stringify({ accepted, date: Date.now() }));
    setVisible(false);
  };

  if (!visible) return null;

  return (
    <div className="fixed bottom-0 left-0 right-0 z-50 p-4 sm:p-6">
      <div className="max-w-2xl mx-auto glass rounded-2xl border border-white/10 p-5 sm:p-6 shadow-2xl animate-fade-in-up">
        <div className="flex items-start gap-4">
          <div className="flex-1">
            <h4 className="text-sm font-semibold text-white mb-1 font-display">Cookie Consent</h4>
            <p className="text-sm text-gray-400 leading-relaxed">
              We use cookies to enhance your browsing experience, analyze site traffic, and personalize content. By clicking "Accept", you consent to our use of cookies.
            </p>
          </div>
          <button onClick={() => handleAction(false)} className="text-gray-500 hover:text-white p-1 flex-shrink-0">
            <X size={18} />
          </button>
        </div>
        <div className="flex items-center gap-3 mt-4">
          <button onClick={() => handleAction(true)} className="bg-accent-500 hover:bg-accent-400 text-white text-sm font-semibold px-5 py-2 rounded-lg transition-colors">
            Accept
          </button>
          <button onClick={() => handleAction(false)} className="text-sm text-gray-400 hover:text-white transition-colors px-3 py-2">
            Decline
          </button>
        </div>
      </div>
    </div>
  );
}

