import React, { useState } from 'react';
import Nav from '../components/Nav';
import Footer from '../components/Footer';
import { Database, Code2, LayoutDashboard, ArrowRight, CheckCircle2, Server, BarChart3, Workflow, Link2 } from 'lucide-react';

const tabContent = {
  etl: {
    title: 'Automated ETL Pipelines',
    desc: 'Extract, transform, and load data between WellStream and your enterprise systems on schedule. Our managed ETL orchestration handles complex energy data schemas so your team can focus on insights, not infrastructure.',
    features: [
      { icon: Database, label: 'Read-Only Snowflake Access', detail: 'Query your WellStream data directly in Snowflake without impacting production performance.' },
      { icon: BarChart3, label: 'Supports BI Warehousing', detail: 'Feed Power BI, Tableau, or Spotfire with clean, structured energy data pipelines.' },
      { icon: Workflow, label: 'Handles Complex Use Cases', detail: 'Map multi-source data from SCADA, accounting, and regulatory systems into unified schemas.' },
      { icon: Link2, label: 'Improves System Interoperability', detail: 'Bridge legacy databases and modern cloud applications with managed ETL orchestration.' },
    ],
  },
  apis: {
    title: 'RESTful APIs',
    desc: 'Real-time programmatic access for custom applications and third-party integrations. Our well-documented REST APIs enable your development team to build custom workflows, automate processes, and extend the platform to meet unique requirements.',
    features: [
      { icon: Code2, label: 'Full REST API Coverage', detail: 'Access well data, production volumes, land records, and more through standardized endpoints.' },
      { icon: Key, label: 'OAuth 2.0 Authentication', detail: 'Secure API access with industry-standard token-based authentication and granular permissions.' },
      { icon: Activity, label: 'Real-Time Webhooks', detail: 'Subscribe to events and receive push notifications when data changes across the platform.' },
      { icon: Server, label: 'Rate-Limited & Monitored', detail: 'Built-in rate limiting and usage analytics protect platform stability while you scale.' },
    ],
  },
  dashboards: {
    title: 'Configurable Dashboards',
    desc: 'Pre-built and customizable visualization layers surface insights without requiring data exports. Create executive summaries, operational views, and engineering deep-dives — all within the platform.',
    features: [
      { icon: LayoutDashboard, label: 'Pre-Built Templates', detail: 'Ready-to-use dashboard templates for common energy workflows — production monitoring, cost tracking, and compliance.' },
      { icon: BarChart3, label: 'Custom Visualizations', detail: 'Build custom charts, tables, and KPIs with an intuitive drag-and-drop interface.' },
      { icon: Activity, label: 'Live Data Refresh', detail: 'Dashboards update in real-time as new data flows into the platform.' },
      { icon: Share2, label: 'Scheduled Reports', detail: 'Automatically generate and distribute PDF reports to stakeholders on your schedule.' },
    ],
  },
};

// Need to import these for the APIs tab
import { Key, Activity, Share2 } from 'lucide-react';

export default function IntegrationPage() {
  const [activeTab, setActiveTab] = useState<'etl' | 'apis' | 'dashboards'>('etl');

  const current = tabContent[activeTab];

  return (
    <div className="bg-mesh min-h-screen">
      <Nav />

      {/* Hero */}
      <section className="pt-28 pb-14 lg:pt-40 lg:pb-20">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="max-w-3xl">
            <div className="inline-flex items-center gap-2 bg-accent-400/10 border border-accent-400/20 rounded-full px-4 py-1.5 text-xs text-accent-400 font-semibold mb-6 tracking-wider">
              <Link2 size={14} />
              SEAMLESS INTEGRATION
            </div>
            <h1 className="text-4xl sm:text-5xl lg:text-6xl font-extrabold text-white leading-[1.05] tracking-tight mb-6 font-display">
              Connect WellStream<br />
              <span className="text-transparent bg-clip-text bg-gradient-to-r from-accent-400 to-teal-400">With Your Tech Stack</span>
            </h1>
            <p className="text-lg text-gray-400 max-w-2xl leading-relaxed">
              Open APIs, automated ETL pipelines, and pre-built connectors integrate WellStream with your existing systems — from SCADA to accounting to BI tools.
            </p>
          </div>
        </div>
      </section>

      {/* Integration Tabs */}
      <section className="pb-16">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          {/* Tab navigation */}
          <div className="flex flex-wrap gap-3 mb-10">
            {[
              { id: 'etl' as const, icon: Database, label: 'ETL' },
              { id: 'apis' as const, icon: Code2, label: 'APIs' },
              { id: 'dashboards' as const, icon: LayoutDashboard, label: 'Dashboards' },
            ].map((tab) => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`flex items-center gap-2.5 px-6 py-3 rounded-xl text-sm font-semibold transition-all duration-200 ${
                  activeTab === tab.id
                    ? 'bg-accent-500 text-white shadow-lg shadow-accent-500/20'
                    : 'bg-white/5 text-gray-400 hover:text-white hover:bg-white/10 border border-white/5'
                }`}
              >
                <tab.icon size={17} />
                {tab.label}
              </button>
            ))}
          </div>

          {/* Tab content */}
          <div className="glass rounded-2xl p-8 sm:p-10 border border-white/10 transition-all duration-300">
            <h2 className="text-2xl sm:text-3xl font-bold text-white mb-4 font-display">{current.title}</h2>
            <p className="text-gray-400 leading-relaxed mb-8 max-w-3xl">{current.desc}</p>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
              {current.features.map((feat, i) => (
                <div key={i} className="flex items-start gap-4 p-5 rounded-xl bg-white/[0.02] border border-white/[0.03] hover:border-accent-400/10 transition-colors">
                  <div className="w-10 h-10 rounded-lg bg-accent-400/10 border border-accent-400/20 flex items-center justify-center flex-shrink-0">
                    <feat.icon size={18} className="text-accent-400" />
                  </div>
                  <div>
                    <h4 className="text-sm font-semibold text-white mb-1">{feat.label}</h4>
                    <p className="text-xs text-gray-400 leading-relaxed">{feat.detail}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* ETL Benefits (shown always) */}
      <section className="py-16 bg-navy-950/50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-12">
            <h2 className="text-3xl sm:text-4xl font-bold text-white font-display">ETL Key Benefits</h2>
            <p className="text-gray-400 mt-3 max-w-xl mx-auto">Managed data pipelines that scale with your operations.</p>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 max-w-4xl mx-auto">
            {[
              { icon: Database, title: 'Read-Only Snowflake Access', desc: 'Query your WellStream data directly in Snowflake without impacting production performance.' },
              { icon: BarChart3, title: 'Supports BI Warehousing', desc: 'Feed Power BI, Tableau, or Spotfire with clean, structured energy data pipelines.' },
              { icon: Workflow, title: 'Handles Complex Use Cases', desc: 'Map multi-source data from SCADA, accounting, and regulatory systems into unified schemas.' },
              { icon: Link2, title: 'Improves System Interoperability', desc: 'Bridge legacy databases and modern cloud applications with managed ETL orchestration.' },
            ].map((item, i) => (
              <div key={i} className="glass rounded-xl p-6 border border-white/5 flex items-start gap-4">
                <div className="w-10 h-10 rounded-lg bg-brand-green/10 border border-brand-green/20 flex items-center justify-center flex-shrink-0">
                  <item.icon size={18} className="text-brand-green" />
                </div>
                <div>
                  <h3 className="text-sm font-semibold text-white mb-1.5">{item.title}</h3>
                  <p className="text-xs text-gray-400 leading-relaxed">{item.desc}</p>
                </div>
              </div>
            ))}
          </div>

          <div className="text-center mt-10">
            <a href="request-demo.html" className="inline-flex items-center gap-2 bg-accent-500 hover:bg-accent-400 text-white font-semibold px-8 py-3.5 rounded-xl transition-all duration-200 shadow-lg shadow-accent-500/20">
              Schedule an Integration Review <ArrowRight size={18} />
            </a>
          </div>
        </div>
      </section>

      <Footer />
    </div>
  );
}

