import Nav from '../components/Nav';
import Footer from '../components/Footer';
import { ArrowRight, CheckCircle2, Globe, Phone, Mail, MapPin } from 'lucide-react';

interface FormData {
  firstName: string;
  lastName: string;
  email: string;
  company: string;
  phone: string;
  jobTitle: string;
  country: string;
  comments: string;
}

interface FormErrors {
  [key: string]: string;
}

const countries = [
  'United States', 'Canada', 'Mexico', 'Brazil', 'Argentina', 'Colombia',
  'United Kingdom', 'Norway', 'Netherlands', 'Germany',
  'Saudi Arabia', 'UAE', 'Qatar', 'Kuwait', 'Oman',
  'Nigeria', 'Angola', 'Egypt', 'Libya',
  'Australia', 'Indonesia', 'Malaysia', 'India', 'China',
];

const supportRegions = [
  { region: 'North America', email: 'support-na@wellstream.com', phone: '+1 (855) 555-0199' },
  { region: 'Latin America', email: 'support-latam@wellstream.com', phone: '+52 (55) 5550-1982' },
  { region: 'Middle East & North Africa', email: 'support-mena@wellstream.com', phone: '+971 (4) 555-0187' },
];

export default function RequestDemoPage() {
  const [form, setForm] = useState<FormData>({
    firstName: '', lastName: '', email: '', company: '', phone: '', jobTitle: '', country: '', comments: '',
  });
  const [errors, setErrors] = useState<FormErrors>({});
  const [submitted, setSubmitted] = useState(false);

  const validate = (): boolean => {
    const errs: FormErrors = {};
    if (!form.firstName.trim()) errs.firstName = 'First name is required';
    if (!form.lastName.trim()) errs.lastName = 'Last name is required';
    if (!form.email.trim()) errs.email = 'Business email is required';
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) errs.email = 'Please enter a valid email';
    if (!form.company.trim()) errs.company = 'Company is required';
    if (!form.jobTitle.trim()) errs.jobTitle = 'Job title is required';
    if (!form.country) errs.country = 'Country is required';
    setErrors(errs);
    return Object.keys(errs).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (validate()) {
      setSubmitted(true);
      window.scrollTo({ top: 0, behavior: 'smooth' });
